union SensorData {
    int raw_adc;
    float processed_temp;
    char buffer[8];
};

union SensorData sd;

// 1. Use raw_adc field
sd.raw_adc = 4095;
int reading = sd.raw_adc;

// 2. Use processed_temp (memory reused)
sd.processed_temp = 98.6f;
float temp = sd.processed_temp;

// Accessing the other field now yields garbage
// (sd.raw_adc is corrupted due to float assignment)

